import chess
import time

fen = "rbrk1r2/1p2p1p1/p1n1p3/3nPp1Q/8/P1N5/1P1K1PQ1/R1B1B2R w KQ - 0 1"
board = chess.Board(fen)

PIECE_VALUES = {
    chess.PAWN: 100, chess.KNIGHT: 320, chess.BISHOP: 330,
    chess.ROOK: 500, chess.QUEEN: 900, chess.KING: 20000
}

def evaluate(board):
    score = 0
    for sq in chess.SQUARES:
        p = board.piece_at(sq)
        if p:
            v = PIECE_VALUES[p.piece_type]
            if p.color == chess.WHITE:
                score += v
            else:
                score -= v
    # Add positional bonus for king safety
    return score

def minimax(board, depth, alpha, beta, maximizing):
    if depth == 0:
        return evaluate(board)
    if board.is_checkmate():
        return -99999 if maximizing else 99999
    if board.is_stalemate() or board.is_insufficient_material():
        return 0

    if maximizing:
        max_eval = -float('inf')
        moves = list(board.legal_moves)
        moves.sort(key=lambda m: (board.piece_at(m.to_square) is not None, 0), reverse=True)
        for move in moves:
            board.push(move)
            ev = minimax(board, depth-1, alpha, beta, False)
            board.pop()
            max_eval = max(max_eval, ev)
            alpha = max(alpha, ev)
            if beta <= alpha:
                break
        return max_eval
    else:
        min_eval = float('inf')
        moves = list(board.legal_moves)
        moves.sort(key=lambda m: (board.piece_at(m.to_square) is not None, 0), reverse=True)
        for move in moves:
            board.push(move)
            ev = minimax(board, depth-1, alpha, beta, True)
            board.pop()
            min_eval = min(min_eval, ev)
            beta = min(beta, ev)
            if beta <= alpha:
                break
        return min_eval

# Check for forced mate within 6 plies (3 moves each side)
print("Checking for forced mate in 3 (6 plies)...")
start = time.time()
mate_moves = []
for move in board.legal_moves:
    san = board.san(move)
    board.push(move)
    if board.is_checkmate():
        mate_moves.append((san, move.uci(), "mate in 1"))
    else:
        # Check if all black responses lead to mate in 2
        all_mated = True
        for bmove in board.legal_moves:
            board.push(bmove)
            found_mate = False
            for wmove in board.legal_moves:
                board.push(wmove)
                if board.is_checkmate():
                    found_mate = True
                board.pop()
            board.pop()
            if not found_mate:
                all_mated = False
                break
        if all_mated:
            mate_moves.append((san, move.uci(), "mate in 2"))
    board.pop()

if mate_moves:
    print(f"Found {len(mate_moves)} forced mate moves:")
    for san, uci, desc in mate_moves:
        print(f"  {san} ({uci}) - {desc}")
else:
    print("No forced mate in 2 found")

print(f"Time: {time.time()-start:.1f}s")

# Now let me check: what is the best move considering the position?
# Qxg7 is the top candidate. Let me trace the best line after Qxg7
print("\n=== Best line after 1.Qxg7 ===")
board.push(chess.Move.from_uci("g2g7"))
# Black's best response - try each and see white's best
for bmove in list(board.legal_moves):
    bsan = board.san(bmove)
    board.push(bmove)
    # White's best response
    best_w = None
    best_ev = -float('inf')
    for wmove in list(board.legal_moves):
        board.push(wmove)
        if board.is_checkmate():
            best_ev = 99999
            best_w = wmove
        else:
            ev = minimax(board, 2, -float('inf'), float('inf'), False)
            if ev > best_ev:
                best_ev = ev
                best_w = wmove
        board.pop()
    board.pop()
    if best_w:
        wsan = board.san(chess.Move.from_uci(best_w.uci())) if best_w else "?"
        print(f"  1.Qxg7 {bsan} 2.{wsan} -> eval {best_ev:+d}")
